def finish(p):
 T={x['key']:x for x in json.loads((p.D/'author-transcripts-extra.json').read_text())['transcripts']}
 rows={r['id']:r for r in p.rows}
 def new(sid,zh,en,label,tex,pages,kind='derivation'):
  r=p.result('transformation-'+sid,zh,en,label,tex,[('formal',pages,label)],[],kind=kind)
  rows[r['id']]=r;return r
 def get(s):return rows['transformation-'+s]
 def source(s,key,text=None,pages=None,statement=None):
  r=get(s);t=T[key];pages=pages or t['source_pages'];text=text if text is not None else t['original_proof_md']
  r['original_proof_md']=text.strip();r['original_proof_refs']=[p.ref('formal',pages,t['section'])]
  r['original_proof_source_type']='complete_manual_formal_proof_transcription'
  r['original_statement_md']=statement if statement is not None else t['original_statement_md']
  r['source_transcription_notes']=[dict(note=x,attribution='project_source_note_not_author_text') for x in t.get('transcription_notes',[])]
  (p.D/'original-proofs'/f"{r['id']}.md").write_text(text.strip()+'\n')
 def block(s,key,start,end=None,pages=None):
  txt=T[key]['original_proof_md'];a=txt.index(start);b=txt.index(end,a+len(start)) if end else len(txt)
  text=txt[a:b].strip();source(s,key,text,pages,statement=text.split('Proof.')[0].strip() if 'Proof.' in text else text)
 def pair_items(id,items):return ([dict(id=f'{id}-{j}',body_md=z) for j,(z,e) in enumerate(items,1)], [dict(id=f'{id}-{j}',body_md=e) for j,(z,e) in enumerate(items,1)])
 LAW=(r'有限门/标签联合律$p$满足$p\ge0$、$\sum p=1$。定义$H(p)=-\sum_a p_a\log p_a$、$H(B\mid A)=\sum_a p_aH(p(\cdot\mid a))$；$p_a=0$整行贡献0，不要求全支撑正质量。',r'A finite gate/label joint law satisfies $p\ge0$ and $\sum p=1$. Define $H(p)=-\sum_a p_a\log p_a$ and $H(B\mid A)=\sum_a p_aH(p(\cdot\mid a))$. A zero-mass conditioning row contributes zero; full positive support is unnecessary.')
 GATE=(r'输入$X$可在任意可测空间取值，分布为$\mu$。无额外采样/dropout时门是确定性$f(X)$；标签条件律$k_x(y)=P(Y=y\mid X=x)$与门来自同一概率模型。$p(y,\sigma)=\int1_{f(x)=\sigma}k_x(y)d\mu(x)$，原子概率核可测。',r'The input may take values in any measurable space with law $\mu$. Without additional sampling/dropout, the gate is deterministic $f(X)$. The conditional label law $k_x(y)=P(Y=y\mid X=x)$ belongs to the same probability model. The joint law is $p(y,\sigma)=\int1_{f(x)=\sigma}k_x(y)d\mu(x)$, with measurable atom kernels.')
 CO=(r'采用原作者co-information约定$ I(X;\Sigma;Y)=I(\Sigma;Y)-I(\Sigma;Y\mid X)$。其中条件MI是$\int I(k_x(y)1_{f(x)=\sigma})d\mu(x)$。只使用有限标签/门的熵，不要求连续$X$存在离散Shannon熵。',r'Use the author co-information convention $ I(X;\Sigma;Y)=I(\Sigma;Y)-I(\Sigma;Y\mid X)$. Conditional MI is $\int I(k_x(y)1_{f(x)=\sigma})d\mu(x)$. Only finite label/gate entropy is used; a discrete Shannon entropy of continuous input is unnecessary.')
 TC=(r'对二值门向量定义边缘$p_d$、$TC(p)=D_{KL}(p\Vert\prod_dp_d)$、$C=\sum_dH(p_d)$。$TC(\Sigma\mid Y)=\sum_yp_yTC(p(\Sigma\mid y))$，$C_{\mid Y}=\sum_yp_y\sum_dH(p(\Sigma^d\mid y))$。正联合原子使对应边缘原子正，KL在真支撑上可定义。',r'For a binary gate vector, let $p_d$ be its marginals and define $TC(p)=D_{KL}(p\Vert\prod_dp_d)$ and $C=\sum_dH(p_d)$. Define $TC(\Sigma\mid Y)=\sum_yp_yTC(p(\Sigma\mid y))$ and $C_{\mid Y}=\sum_yp_y\sum_dH(p(\Sigma^d\mid y))$. A positive joint atom has positive corresponding marginal atoms, so KL is defined on the actual support.')
 KDE=(r'样本核$K_h(s,t)=\exp[-\|s-t\|^2/(2h)]$，$h=\sigma_0^2>0$。门控段原规定$h=\kappa\operatorname{Var}(\Sigma)$、$\kappa>0$；连续加噪特征段的$h$是任意正Gaussian方差。核估计不自动等于离散Shannon熵。',r'The sample kernel is $K_h(s,t)=\exp[-\|s-t\|^2/(2h)]$, with $h=\sigma_0^2>0$. The gate section specifies $h=\kappa\operatorname{Var}(\Sigma)$ and $\kappa>0$; the continuous noisy-feature section permits any positive Gaussian variance. A kernel estimate is not automatically a discrete Shannon entropy.')
 EBM=(r'有限门状态$\mathcal S$；先验$q$正规，分数$f_\theta$为实数。定义$Z_\theta=\sum_{s\in\mathcal S}q(s)e^{f_\theta(s)}$、$p_\theta(s)=q(s)e^{f_\theta(s)}/Z_\theta$。真实经验律$r$的支撑上$q>0$；取实际门边缘乘积先验时此条件可推出，包括激活率0/1。',r'The gate state space $\mathcal S$ is finite, the prior $q$ is normalized and the score $f_\theta$ is real. Define $Z_\theta=\sum_{s\in\mathcal S}q(s)e^{f_\theta(s)}$ and $p_\theta(s)=q(s)e^{f_\theta(s)}/Z_\theta$. The prior is positive on the true empirical support of $r$; this follows for the actual product of gate marginals, including activation rates zero or one.')
 def spec(s,assumptions,definitions,steps,scope,role='proof',assessment='no_statement_error_recorded',evidence=None):
  r=get(s);r['assumptions'],ea=pair_items(r['id']+'-assumption',assumptions);r['definitions'],ed=pair_items(r['id']+'-definition',definitions)
  st=[];es=[]
  for j,t in enumerate(steps,1):
   ztitle,etitle,z,e,tex,ln=t;sid=f"{r['id']}-step-{j}"
   st.append(dict(id=sid,title=ztitle,body_md=z,formula_tex=tex,justification='',lean_refs=['Harsanyi.Entropy.'+n if '.' not in n else n for n in ln]))
   es.append(dict(id=sid,title=etitle,body_md=e,justification=''))
  r['proof_steps']=st;r['overview']=st[0]['body_md'];r['rewrite_role']=role;r['statement_assessment']=assessment;r['rewrite_status']='complete';r['scope']=scope[0];r['proof_scope']='full_original_statement' if role=='proof' else 'counterexample_to_original_statement' if role=='counterexample' else 'explicit_component_and_source_scope'
  names=list(dict.fromkeys(n for x in st for n in x['lean_refs']))
  ev=evidence or ('theorem_proof' if role=='proof' and names else 'counterexample' if role=='counterexample' and names else 'partial_component' if names else 'none')
  if r['id']=='transformation-kde-labels':ev='partial_component'
  r['lean']=dict(status='pending_verification' if names else 'not_formalized' if r['kind'].startswith('external') else 'not_applicable',compiled=False,evidence_role=ev,declarations=names,scope=scope[0],translations={'en':dict(scope=scope[1])})
  r['translations']['en'].update(assumptions=ea,definitions=ed,proof_steps=es,overview=es[0]['body_md'],scope=scope[1]);r['related_issue_ids']=[]
  return r
 def step(zt,et,z,e,tex='',ln=[]):return(zt,et,z,e,tex,ln)
 # Faithful source boundaries. Repeated numbered equations retain every occurrence.
 source('gating-affine','A',statement=r'Given the input $\mathbf x\in\mathcal X$ and the target label $y\in\mathcal Y$, the DNN is learned to map $\mathbf x$ to $y$. Layerwise transformations can be roughly represented by $$y=g(z),\quad z=W_{L+1}\cdots\boldsymbol\sigma_2(W_2\boldsymbol\sigma_1(W_1\mathbf x+b_1)+b_2)\cdots+b_{L+1}.\tag{1}$$ Here $g$ is an optional top layer such as softmax; the module before it is piecewise linear. For a given input, the transformation is $z=W\mathbf x+b$, where $W=W_{L+1}\boldsymbol\sigma_LW_L\cdots\boldsymbol\sigma_2W_2\boldsymbol\sigma_1W_1$ and $b$ is the equivalent bias. Different inputs can generate different gate matrices and hence different $W,b$.' )
