 new('ebm-dnn-gradient','冻结EBM后的DNN梯度','DNN gradient with the EBM frozen','Eq.(40)',r'\partial_\theta\mathcal L=-n^{-1}\sum_{l,i}(\partial_\sigma f+\partial_\sigma\log q)\partial_\theta\sigma_{l,i}',[20]);block('ebm-dnn-gradient','F',fm[5],fm[6],[20])
